  "capabilities": [
    {
      "capability_id": "move_end_effector",
      "method_name": "move_end_effector",
      "description": "Move the Piper ee_site to a commanded world-frame Cartesian position. Single-effect: terminal EE position. Does not change gripper aperture or wrist roll.",
      "effect": "ee_site reaches target_xyz within a position tolerance in the world frame.",
      "request_schema": {
        "type": "object",
        "additionalProperties": false,
        "required": ["target_xyz"],
        "properties": {
          "target_xyz": {
            "type": "array",
            "items": {"type": "number"},
            "minItems": 3,
            "maxItems": 3,
            "description": "Desired world-frame position [x, y, z] of ee_site in metres.",
            "unit": "m",
            "frame": "world"
          },
          "duration": {
            "type": "number",
            "minimum": 0.1,
            "maximum": 10.0,
            "description": "Motion duration in seconds. Optional; default chosen by implementation.",
            "unit": "s"
          }
        }
      },
      "preconditions": [
        "target_xyz is within the Piper reachable workspace.",
        "No active grasp or contact force that would prevent free EE motion."
      ],
      "temporal_semantics": {"kind": "bounded_terminal_effect", "note": "EE reaches target_xyz and holds at end of motion."},
      "invariants": [
        "Gripper aperture is unchanged throughout the motion.",
        "Joint limits [joint1-joint6] are not violated."
      ],
      "failure_behavior": "Returns False and halts motion if IK is infeasible or joint limits are exceeded; EE position is undefined on failure.",
      "criteria": [
        {
          "metric": "end_effector_target_distance",
          "unit": "m",
          "comparator": "<=",
          "threshold": 0.05,
          "temporal": {"kind": "terminal_state"},
          "aggregation": {"kind": "single_trial"},
          "source_refs": [
            {
              "source_id": "metaworld_repo",
              "specific_reference": "metaworld/envs/sawyer_reach_v3.py, evaluate_state, lines 74-98: success is reach_dist <= 0.05.",
              "support": "adapted",
              "adaptation": "Retain the 0.05 m Euclidean endpoint obligation and apply it to the Piper ee_site in the canonical MuJoCo metre frame."
            }
          ]
        }
      ]
    },
    {
      "capability_id": "set_gripper_aperture",
      "method_name": "set_gripper_aperture",
      "description": "Set the Piper parallel-jaw gripper to a commanded slide-position value. Single-effect: gripper joint7 position. Does not move the arm.",
      "effect": "Gripper actuator 'gripper' (joint7) reaches the commanded slide position in [0.0, 0.035] m; joint8 mirrors via equality constraint.",
      "request_schema": {
        "type": "object",
        "additionalProperties": false,
        "required": ["aperture_m"],
        "properties": {
          "aperture_m": {
            "type": "number",
            "minimum": 0.0,
            "maximum": 0.035,
            "description": "Target gripper slide position in metres. 0.0 = fully closed, 0.035 = fully open.",
            "unit": "m",
            "frame": "gripper"
          },
          "settle_steps": {
            "type": "integer",
            "minimum": 1,
            "maximum": 500,
            "description": "Number of simulation steps to settle after commanding. Optional."
          }
        }
      },
      "preconditions": [
        "aperture_m is in [0.0, 0.035].",
        "Arm joints are stationary or near-stationary."
      ],
      "temporal_semantics": {"kind": "bounded_terminal_effect", "note": "Gripper reaches commanded aperture and holds."},
      "invariants": [
        "Arm joint positions are unchanged during gripper actuation.",
        "joint8 mirrors joint7 via the polycoef equality constraint at all times."
      ],
      "failure_behavior": "If aperture_m is out of range, clamps to [0.0, 0.035] and logs a warning; returns False if settle fails.",
      "criteria": [
        {
          "metric": "gripper_aperture_error",
          "unit": "m",
          "comparator": "<=",
          "threshold": 0.003,
          "temporal": {"kind": "terminal_state"},
          "aggregation": {"kind": "single_trial"},
          "source_refs": [
            {
              "source_id": "metaworld_repo",
              "specific_reference": "metaworld/envs/sawyer_pick_place_v3.py, task_parameters grasp_gripper: native slide-position control in [0, 0.035] m; 0 m closed, 0.035 m open.",
              "support": "adapted",
              "adaptation": "Proposed 0.003 m aperture settling tolerance for the Piper joint7 slide actuator; no source numeric gripper-settling bound is published. This stage does not establish calibration."
            }
          ]
        }
      ]
    },
    {
