      "temporal_semantics": {"kind": "bounded_terminal_effect", "note": "EE reaches target_xyz and joint6 reaches wrist_roll_rad at end of motion."},
      "invariants": [
        "Gripper aperture is unchanged throughout the motion.",
        "Joint limits for joint1-joint6 are not violated."
      ],
      "failure_behavior": "Returns False and halts if IK is infeasible or wrist_roll_rad is out of range.",
      "criteria": [
