      "temporal_semantics": {"kind": "bounded_terminal_effect", "note": "EE reaches terminal_xyz at end of motion; contact force is applied during the push segment."},
      "invariants": [
        "Gripper aperture is unchanged throughout the motion.",
        "Joint limits for joint1-joint6 are not violated."
      ],
      "failure_behavior": "Returns False if IK is infeasible at either waypoint; partial motion may occur if contact blocks terminal_xyz.",
