        {
          "metric": "end_effector_terminal_position_error",
          "unit": "m",
          "comparator": "<=",
          "threshold": 0.05,
          "temporal": {"kind": "terminal_state"},
          "aggregation": {"kind": "single_trial"},
          "source_refs": [
            {
              "source_id": "metaworld_repo",
