        "type": "object",
        "additionalProperties": false,
        "required": ["waypoint_xyz", "final_xyz"],
        "properties": {
          "waypoint_xyz": {
            "type": "array",
            "items": {"type": "number"},
            "minItems": 3,
            "maxItems": 3,
            "description": "Intermediate world-frame position [x, y, z] of ee_site in metres.",
