            "minimum": 0.1,
            "maximum": 10.0,
            "description": "Duration in seconds for the segment from waypoint_xyz to final_xyz. Optional.",
            "unit": "s"
          }
        }
      },
      "preconditions": [
        "waypoint_xyz and final_xyz are within the Piper reachable workspace.",
        "Both segments are kinematically feasible without joint-limit violation."
      ],
      "temporal_semantics": {"kind": "bounded_terminal_effect", "note": "EE visits waypoint_xyz then reaches final_xyz; ordering is enforced."},
      "invariants": [
